    def fit(c):
        ys=[math.log(v/c[0]) for v in c]; mt=sum(t)/4; my=sum(ys)/4
        slope=sum((a-mt)*(b-my) for a,b in zip(t,ys))/sum((a-mt)**2 for a in t); intercept=my-slope*mt
