    print(json.dumps({'entry':binding(entry),'freeze':binding(freeze),'candidateSet':binding(cset),'profiles':19,'workedTransfers':38,'maxBriefText':max_text,'freshKineticSlope':newfit[1],'freshKineticIntercept':newfit[2],'fresh20Residual':newfit[3][2]},ensure_ascii=False,indent=2))

